        if(shape)try{await log.add('stock-sell-receipt-shape','手动卖出成功回执：到账金额与字段结构',
          {source:'manual',receiptShape:shape,proceeds:e.proceeds??null},true,'stock-sale-shape:'+id);}catch{ /* 诊断失败不影响原收入核对。 */ }
