      const original=row.p;let outfitId=original.outfitId,weaponId=original.weaponId;
      for(const c of changes)if(['outfit','weapon'].includes(c.slot)){
        if(c.slot==='outfit'){if(c.id===original.id)outfitId=c.item;else if(outfitId===c.item)outfitId=null;}
        else {if(c.id===original.id)weaponId=c.item;else if(weaponId===c.item)weaponId=null;}
      }
