    const pool=new Set(s.residents.filter(eligible).map(p=>p.id)),departure=shelterProductionEvaluator(m);
    const free=s.residents.some(p=>{
      if(!pool.has(p.id)||!['power','diner','water'].includes(s.rooms.find(r=>r.id===p.roomId)?.type))return false;
      const after=departure([p.id]);return Object.entries(demand).every(([k,n])=>after[k]>=n*1.2-1e-9);
    });
