      if(pair.some(o=>o.adultAt>now))reasons.push('有人尚未成年');
      if(pair.some(o=>Number.isFinite(o.happiness)&&o.happiness<50))reasons.push('两人的心情都需要达到 50');
      if(pair.some(o=>o.familyCooldownUntil>now))reasons.push('生育冷却尚未结束');
