    m={...m,trainingDestinations:campaign.trainingDestinations||[]};
    const dailySupply=shelterGrowthNeeds(m).demand;
    // 日目标保留的人手也约束普通调岗，避免刚补餐厅又被产废料优化调走；基础供应不足时先救供应。
    if(Object.keys(dailySupply).every(k=>m.production[k]>=dailySupply[k]*1.2-1e-9))
      for(const id of campaign.dailyReserved)campaignReserved.add(id);
    // 调岗比领奖需要更多字段；缺少证据只停止人员管理，仍可收取奖励。
    if (new Set(s.residents.map(p => p.id)).size !== s.residents.length || s.residents.some(p =>
      typeof p.name !== 'string' || !p.name.trim() || !Number.isFinite(p.hp) || p.hp < 0 ||
      !(p.roomId === null || Number.isSafeInteger(p.roomId)) || !Array.isArray(p.parents) ||
      !p.parents.every(Number.isSafeInteger) || !(p.familyCooldownUntil == null || Number.isFinite(p.familyCooldownUntil)) ||
      !(p.romance == null || objectState(p.romance) && Number.isSafeInteger(p.romance.partnerId))) ||
      s.births.some(b => !Number.isSafeInteger(b.roomId) || !s.rooms.some(r => r.id === b.roomId && r.type === 'quarters'))) throw new Error('人员或待产信息不完整');
    const familyMode = ['family','population'].includes(shelterStaffMode), populationMode = shelterStaffMode === 'population';
    if (populationMode && shelterPopulationTarget === null) { holdShelterStaff('人口目标无效，本轮只收取奖励，请重新设置目标'); return null; }
    const families = familyMode ? rememberShelterFamilies(m) : [];
    const home = p => p.deadAt === null && p.away === null && p.adultAt <= m.now;
    const healthy = p => p.hp >= .6*Math.round(100+(Math.min(50,1+Math.floor(Math.sqrt(p.xp/3)))-1)*(2+.5*p.stats.end));
    const byRoom = id => s.rooms.find(r => r.id === id);
    const familyOf = p => families.find(f => f.a === p.id || f.b === p.id);
    const birthRooms = new Set(s.births.map(b => b.roomId));
    const expecting = new Set(s.births.flatMap(b=>shelterBirthParents(s,b)||[]));
    const unknownBirthRooms = new Set(s.births.filter(b=>!shelterBirthParents(s,b)).map(b=>b.roomId));
    const romanceResidents = new Set(s.residents.filter(p => p.deadAt === null && p.romance &&
      !shelterFamilyExpecting(s,p.id,p.romance.partnerId)).flatMap(p => [p.id,p.romance.partnerId]));
    const protectedParent = p => families.some(f => [f.a,f.b].includes(p.id) && unknownBirthRooms.has(f.room));
    const occupancy = id => s.residents.filter(p => p.deadAt === null && p.adultAt <= m.now && p.roomId === id).length;
    const recovering = shelterRecoveringPopulation(s);
    const population = s.residents.filter(p => p.deadAt === null).length+s.births.length+recovering;
    const eligible = p => {
      if (campaignReserved.has(p.id) || !home(p) || !healthy(p) || romanceResidents.has(p.id) || unknownBirthRooms.has(p.roomId) || protectedParent(p)) return false;
      if(!identityChecks.has(p))identityChecks.set(p,Boolean(shelterResidentIdentity(s,p,identityNames)));
      if(!identityChecks.get(p))return false;
      const old = byRoom(p.roomId);
      if (old?.incident || old?.upgradeAt != null || old && old.builtAt > m.now) return false;
      if (p.roomId === null || old && staffRoomTypes.includes(old.type)) return true;
      if (shelterTrainingComplete(s,p)) return true;
      if (old?.type !== 'quarters') return false;
      if (expecting.has(p.id)) return true;
      const f = familyOf(p);
      if (f && f.room === old.id) return p.familyCooldownUntil > m.now || population >= (populationMode ? Math.min(shelterPopulationTarget,m.populationCap) : m.populationCap);
      // 历史手动住宿不是永久岗位；真实感情、待产及已预约家庭已在上面保护。
      return true;
    };
    // 已有感情的父母可能在防守结束后分处生产岗与休息区。保护关系不能变成永久禁止团聚。
    // 仅恢复双方相互确认的原配对，不从普通调岗池借用这两人，也不挪动训练或其他特殊岗位。
    const interruptedFamilies=populationMode?families.filter(f=>{
      const pair=[f.a,f.b].map(id=>s.residents.find(p=>p.id===id)),room=byRoom(f.room);
      return room?.type==='quarters'&&room.builtAt<=m.now&&room.upgradeAt===null&&!room.incident&&!room.unpowered&&
        !birthRooms.has(f.room)&&!s.residents.some(p=>home(p)&&p.roomId===f.room&&![f.a,f.b].includes(p.id))&&
        pair.some(p=>p?.roomId!==f.room)&&pair.every((p,i)=>p&&home(p)&&healthy(p)&&p.happiness>=50&&
          !(p.familyCooldownUntil>m.now)&&p.romance?.partnerId===pair[1-i]?.id&&!campaignReserved.has(p.id)&&
          shelterResidentIdentity(s,p,identityNames)&&
          (p.roomId===null||p.roomId===f.room||staffRoomTypes.includes(byRoom(p.roomId)?.type)&&
            byRoom(p.roomId).builtAt<=m.now&&byRoom(p.roomId).upgradeAt===null&&!byRoom(p.roomId).incident))&&
        populationHousingSupply(m,families,pair).allowed;
    }):[];
    if (populationMode && shelterState.pair) {
      const next = shelterPopulationPlan(m,families,{eligible,home,healthy});
      if (next || shelterStaffHold) return next;
    }
    // 在为旧组合抽调接替者之前比较可立即执行的新组合；不能让旧家庭的准备流程永久挡住更优父母。
    if(populationMode&&!interruptedFamilies.length&&!skippedFamilies.length&&!campaign.defense?.busy&&!shelterState.pair&&
        Object.keys(dailySupply).every(k=>m.production[k]>=dailySupply[k]*1.2-1e-9)){
      const next=shelterPopulationPlan(m,families,{eligible,home,healthy},true,true);
      if(next||shelterStaffHold||shelterState.pair)return next;
    }
    const pool = s.residents.filter(p => eligible(p) && !(populationMode && shelterState.pair && [shelterState.pair.a,shelterState.pair.b].includes(p.id)));
    const future = populationMode ? shelterPopulationPreparation(m,families,campaign) : 0;
    const readyFamilies = families.filter(f => {
      const pair = [f.a,f.b].map(id => s.residents.find(p => p.id === id)), room = byRoom(f.room);
      return room?.type === 'quarters' && room.builtAt <= m.now && room.upgradeAt === null && !room.incident && !room.unpowered &&
        !birthRooms.has(room.id) && pair.every(p => home(p) && healthy(p) && p.happiness >= 50 && (!p.romance||interruptedFamilies.includes(f)) && !(p.familyCooldownUntil > m.now) &&
          (p.roomId === room.id || eligible(p)||interruptedFamilies.includes(f))) &&
        !s.residents.some(p => p.deadAt === null && p.adultAt <= m.now && p.roomId === room.id && ![f.a,f.b].includes(p.id));
    }).sort((a,b)=>Number(interruptedFamilies.includes(b))-Number(interruptedFamilies.includes(a)));
    const recoveryDemand = shelterGrowthNeeds(m,populationMode?campaign.populationPreparation:null,shelterPopulationTarget).demand;
    const constructionProject=!campaign.defense?.busy&&(shelterConstruction.build||shelterConstruction.upgrade||shelterConstruction.dig)?
      shelterDevelopmentPlan(m,shelterPopulationTarget,campaign,shelterLevelTarget).next.project:null;
    const workshopPreparation=campaign.workshopPreparation?.project===constructionProject?campaign.workshopPreparation:null;
    const constructionPower=interruptedFamilies.length||constructionProject?.powerStaffing&&readyFamilies.length?0:Math.max(
      shelterConstructionPowerReserve(constructionProject,m,shelterConstruction,shelterState,shelterPending,Date.now()),
      workshopPreparation?.powerReserve||0);
    recoveryDemand.power+=constructionPower;
    const familyBirth = familyMode && !populationMode && recovering && population < m.populationCap && readyFamilies.length ? 1 : 0;
    const baseDemand = populationMode ? {...recoveryDemand,food:Math.max(recoveryDemand.food,future),water:Math.max(recoveryDemand.water,future)} :
      familyBirth ? {...recoveryDemand,food:recoveryDemand.food+1,water:recoveryDemand.water+1} : recoveryDemand;
    let preparation = null;
    if (populationMode && !shelterState.pair) {
      const pending = shelterState.swap?.prepareFamily, familyIds = f => [Math.min(f.a,f.b),Math.max(f.a,f.b),f.room];
      const candidates = readyFamilies.filter(f => pending ? JSON.stringify(pending) === JSON.stringify(familyIds(f)) :
        !skippedFamilies.includes(familyKey(f.a,f.b)) && [f.a,f.b].some(id => s.residents.find(p => p.id === id).roomId !== f.room));
      // 已能返回的家庭先返回；需要接替时只准备一对，避免多对同时抽空基础岗位。
      if (pending || Object.keys(baseDemand).every(k => m.production[k] >= baseDemand[k]*1.2-1e-9) &&
          !candidates.some(f => populationCanHouse(m,families,[f.a,f.b].map(id => s.residents.find(p => p.id === id))))) {
        for (const f of candidates) {
          const supply = populationHousingSupply(m,families,[f.a,f.b].map(id => s.residents.find(p => p.id === id)));
          if (supply.allowed) { preparation = {...supply,prepareFamily:familyIds(f)}; break; }
        }
      }
    }
    if (skippedFamilies.length && !preparation) return null;
    const staffDemand = preparation?.demand || baseDemand;
    const staffModel = {...m,demand:staffDemand,currentDemand:m.demand,
      ...(preparation ? {...preparation,actualProduction:m.production,familySupplies:readyFamilies.map(f=>
        populationHousingSupply(m,families,[f.a,f.b].map(id=>s.residents.find(p=>p.id===id)))).filter(supply=>supply.allowed)} : {})};
    const supplyProduction = staffModel.production;
    const staffPool = preparation ? pool.filter(p => !preparation.reservedResidents.includes(p.id)) : pool;
    if (preparation) shelterPopulationNote = '原家庭正准备返宿舍：先按两人离岗后的产量安排接替，供应和名额重新核对通过后再返回。';
    if (shelterState.swap) {
      const next = shelterSwapStep(staffModel,eligible);
      if (next || shelterStaffHold) return next;
    }
    if (populationMode) for (const f of families) {
      const pair = [f.a,f.b].map(id => s.residents.find(p => p.id === id));
      if (birthRooms.has(f.room) || pair.some(p => !home(p) || p.romance || p.roomId !== f.room && !eligible(p)) || populationCanHouse(m,families,pair)) continue;
      const p = pair.find(p => p.roomId === f.room && healthy(p) && shelterNameUnique(s,p));
      const room = byRoom(f.room);
      if (p && room && room.builtAt <= m.now && !room.incident && room.upgradeAt === null) return {id:p.id,room:null,from:p.roomId,name:p.name,reason:'人口或供应已到限制，原配对暂缓新增生育'};
    }
    const gear = shelterGearPlan(staffModel,staffPool);
    if (gear) return gear;
    const rate = (p,r) => r ? shelterWorkerRate(s,m.now,m.view.env,p,r) : 0;
    const departures=new Map();
    const departureLoss = p => {
      const room=byRoom(p.roomId),resource=room&&shelterRooms[room.type][1];
      if(!resource)return 0;
      if(!departures.has(p.id))departures.set(p.id,supplyProduction[resource]-shelterProductionWithout(staffModel,[p.id])[resource]);
      return departures.get(p.id);
    };
    const safeDonor = p => {
      const r = byRoom(p.roomId), resource = r && shelterRooms[r.type][1];
      const loss=departureLoss(p);
      return (!Object.hasOwn(staffDemand,resource) || loss<=1e-9 || supplyProduction[resource]-loss >= staffDemand[resource]*1.2-1e-9) &&
        (!preparation || shelterDepartureSafe(m,[p.id]));
    };
    const targets = s.rooms.filter(r => staffRoomTypes.includes(r.type) && r.builtAt <= m.now &&
      !r.incident && !r.unpowered && r.upgradeAt === null && occupancy(r.id) < shelterStaffCapacity(m,r));
    const choices = (rooms,reason,allowProductionLoss=false) => rooms.flatMap(r => staffPool.filter(p => p.roomId !== r.id && safeDonor(p)).map(p => {
      const old = byRoom(p.roomId), resource = shelterRooms[r.type][1];
      const output=rate(p,r);
      if(allowProductionLoss&&output<=0)return null;
      const gain = output-(old && shelterRooms[old.type][1] === resource ? departureLoss(p) : 0);
      if(!shelterFamilySupplyPreserved(staffModel,[{id:p.id,room:r.id}]))return null;
      return {id:p.id,room:r.id,from:p.roomId,reason,gain,name:p.name};
    })).filter(c => c&&(allowProductionLoss||c.gain > 1)).sort((a,b) => b.gain-a.gain || a.id-b.id || a.room-b.room);
    const shortages = shelterSupplyShortages(m,staffDemand,supplyProduction);
    for (const resource of shortages) {
      const options = choices(targets.filter(r => shelterRooms[r.type][1] === resource),
        `${preparation ? '原家庭返宿舍前安排接替，' : ''}${constructionPower&&resource==='power'?'为近期工程预留供电，':''}补足${shelterResources[resource]}供应`);
      const support=!preparation&&resource==='power'?constructionProject?.powerStaffing:null;
      const choice = support?options.find(c=>c.id===support.id&&c.room===support.room&&c.from===support.from):options[0];
      if (choice) return choice;
    }
    if(!shortages.length&&!preparation)for(const goal of campaign.dailyProduction||[]){
      if(goal.forecast>=goal.remaining||goal.hours<=0)continue;
      const options=choices(targets.filter(r=>shelterRooms[r.type][1]===goal.resource),
        `补足今日${shelterResources[goal.resource]}目标的整批产量`).filter(c=>!campaign.dailyReserved.includes(c.id)&&
          shelterRooms[byRoom(c.from)?.type]?.[1]!==goal.resource);
      if(options.length)return options[0];
    }
    if (!shortages.length && familyMode && population < m.populationCap && !(populationMode && shelterState.pair)) {
      for (const f of readyFamilies) {
        const pair = [f.a,f.b].map(id => s.residents.find(p => p.id === id)), room = byRoom(f.room);
        // 已回宿舍、尚未开始感情进度的另一对也占用一个预期出生名额。
        const reserved = families.filter(other => other !== f && !shelterFamilyExpecting(s,other.a,other.b) && [other.a,other.b].every(id =>
          s.residents.some(p => p.id === id && home(p) && p.roomId === other.room && !(p.familyCooldownUntil > m.now)))).length;
        if (population+reserved >= m.populationCap) continue;
        if (populationMode && !populationCanHouse(m,families,pair)) continue;
        if (!populationMode) {
          const projected = shelterProductionWithout(m,pair.map(p=>p.id));
          if (!Object.keys(recoveryDemand).every(k => projected[k] >= (recoveryDemand[k]+(k === 'power' ? 0 : 1))*1.2-1e-9 &&
              s.resources[k] >= recoveryDemand[k]*2)) continue;
        }
        const p = pair.find(p => p.roomId !== room.id && shelterDepartureSafe(m,[p.id]));
        if (p && occupancy(room.id) < room.width*2) return {id:p.id,room:room.id,from:p.roomId,name:p.name,
          reason:interruptedFamilies.includes(f)?'恢复已有感情的原配对，供应核对后返回宿舍':'冷却结束，原配对返回宿舍'};
      }
    }
    if (populationMode && !preparation) {
      const next = shelterPopulationPlan(m,families,{eligible,home,healthy},true);
      if (next || shelterStaffHold) return next;
    }
    if (preparation) {
      if (planShelterSwap(staffModel,pool)) return shelterSwapStep(staffModel,eligible);
      // 一对暂时无法接替时，继续检查其他原家庭；不让第一对阻塞全部生育轮换。
      const note = shelterPopulationNote;
      // 递归检查另一家庭时复用原始只读快照。附加训练预留的局部模型不作为新的
      // campaign输入，避免同一居民/库存状态重复做整套供给搜索；状态变化仍由原缓存键失效。
      const next = shelterStaffPlan(planningModel,[...skippedFamilies,familyKey(preparation.prepareFamily[0],preparation.prepareFamily[1])]);
      if (next || shelterStaffHold) return next;
      shelterPopulationNote = note;
    }
    // 已核验就绪的工程交接先开工，普通增产/换位不插队；否则换位临时阻塞工程又会撤掉刚保留的工坊。
    // 基础供应、日目标、家庭及已有换位均已在前面处理；实际开工后重新按扣料状态规划岗位。
    if(!shortages.length&&!preparation&&!pool.some(p=>p.roomId===null||campaign.unemployedResidents.includes(p.id))&&
        ['build','upgrade','dig'].includes(constructionProject?.kind)&&
        (typeof shelterConstructionDone==='undefined'||!shelterConstructionDone)&&
        !shelterConstructionAllowance(constructionProject,m,shelterConstruction,shelterState,shelterPending,Date.now())){
      shelterStaffNote='建设材料与供给已核对，先完成本项开工，再按实际施工状态优化岗位。';return null;
    }
    const material=shelterState.campaign?.materials,project=workshopPreparation?.original||constructionProject;
    if(!shortages.length&&!preparation&&shelterConstruction.upgrade&&!shelterPending&&project?.requiresStaff&&
        validShelterMaterials(material)&&material.vaultNo===m.view.vaultNo&&material.id===project.id&&
        material.type===project.type&&material.level===project.level&&
        ['scrap','parts'].every(k=>project.cost[k]<=shelterConstruction[`${k}Limit`])){
      const destination=targets.find(r=>r.id===project.id);
      // 恢复已确认工程可暂时降低同资源产出；按最小损失选人，仍须真实正产能和原供给安全。
      const replacement=destination&&choices([destination],'为已确认原工程恢复生产者，实际到岗后重新核对备料与开工',true)[0];
      if(replacement)return replacement;
      shelterStaffNote='原工程缺少可安全接岗的生产者，保留缺项，等待实际人手；不按空房产能开工。';return null;
    }
    const projectWorkers=!preparation&&shelterConstruction.upgrade&&!shelterPending&&
      project?.kind==='upgrade'&&staffRoomTypes.includes(project.type)&&project.blocks.every(reason=>
        ['先等一个施工名额空出','扩建后电力余量不足，先补发电'].includes(reason))&&
      (!shelterConstructionAllowance(project,m,shelterConstruction,shelterState,shelterPending,Date.now())||
        (validShelterMaterials(material)&&material.vaultNo===m.view.vaultNo&&material.id===project.id&&material.type===project.type&&material.level===project.level||
          project.type==='scrap'&&!project.levelTarget&&campaign.workshopWorkers.length>0)&&
        project.cost.parts+shelterConstruction.partsReserve>s.resources.parts&&m.production.parts>0)?
      s.residents.filter(p=>p.roomId===project.id&&home(p)&&rate(p,byRoom(p.roomId))>0):[];
    const retainedProducer=projectWorkers.length===1?projectWorkers[0].id:null;
    // 当前备料工程的增产以原岗位有人为前提；不能为邻房短期增产抽空它，再撤工坊、补岗、重开备料。
    // 额度/施工名额或未来工程供电暂不足可以继续备料；已确认的供给房升级与普通回收升级均保留原生产者。
    // 原生产者保护独立于“当前可开工”的供电预留。
    // 已经可以开工的生产房升级同样保留末位生产者，不能抽空后让工程失去增产意义。
    // 基础供给和家庭安排已经先处理；供给房施工暂时零产量也不能让普通回收优化抽空原工程。
    // 取消工程或原房不再符合保留条件后，恢复普通岗位比较。
    const growthPool=retainedProducer===null?pool:pool.filter(p=>p.id!==retainedProducer);
    // 同增产收益时先让待就业成年子女接现有空岗，避免把刚补电的成人立即调回、重新触发就业扩建。
    // 不压过收益更高的原候选或供应、家庭、已有换位；复用原可调人选和离岗安全检查。
    const familySupply=(preparation?readyFamilies:[])
      .map(f=>populationHousingSupply(m,families,[f.a,f.b].map(id=>s.residents.find(p=>p.id===id)))).filter(supply=>supply.allowed);
    // 普通回收增产不能撤销待接替家庭已补好的供应；否则不同家庭轮流评估时，同一人会被反复调回。
    // 分别核对每对家庭，不把全部父母当成同时离岗；供应补位、实际家庭返回和既有换位仍先处理。
    const scrapChoices=choices(targets.filter(r=>r.type==='scrap'),'增加废料生产').filter(c=>c.id!==retainedProducer&&familySupply.every(supply=>{
      const after=shelterProductionWithout({...m,...supply,currentDemand:m.demand,actualProduction:m.production},[c.id]);
      return Object.keys(supply.demand).every(k=>after[k]>=Math.min(supply.production[k],supply.demand[k]*1.2)-1e-9);
    }));
    const bestScrap=scrapChoices[0];
    // 宿舍待就业成人先接确实可用的回收空岗，不把这个直接动作交给可能耗尽搜索额度的整体优化。
    const dormJobs=scrapChoices.filter(c=>byRoom(c.from)?.type==='quarters'&&(campaign.unemployedResidents.includes(c.id)||
      families.some(f=>f.room===c.from&&[f.a,f.b].includes(c.id))&&s.residents.find(p=>p.id===c.id).familyCooldownUntil>m.now));
    // 成年子女需要长期岗位，也应先腾出父母宿舍；临时冷却父母使用余下空位，不抢占子女就业顺序。
    const dormJob=!preparation&&(dormJobs.find(c=>campaign.unemployedResidents.includes(c.id)&&
      !families.some(f=>[f.a,f.b].includes(c.id)))||dormJobs[0]);
    if(dormJob)return {...dormJob,reason:'宿舍待就业成人直接接现有生产空岗，冷却不需要留在宿舍'};
    // 休息区成人同样先接可立即增产的空岗；不必等整组换位才开始生产。
    // 沿用真实容量、预留和供给检查；已有换位及工程交接已在前面接续。
    const idleJob=!preparation&&scrapChoices.find(c=>c.from===null);
    if(idleJob)return {...idleJob,reason:'休息区待就业成人直接接现有生产空岗'};
    // 电站升级已可支付且正为下一工程补电时，先实际开工再做普通增产换位。
